const now = $now.setZone('America/Argentina/Buenos_Aires');
const weekday = now.weekday;
const hour = now.hour;
const laboral = (weekday >= 1 && weekday <= 5) && (hour >= 8 && hour < 18);

const CHAIN = {
  '6h':  { next: '6h2',  delay: { hours: 6 } },
  '6h2': { next: '6h3',  delay: { hours: 6 } },
  '6h3': { next: '24h1', delay: { days: 1 } },
  '24h1':{ next: '24h2', delay: { days: 1 } },
  '24h2':{ next: '24h3', delay: { days: 1 } },
  '24h3':{ next: '72h1', delay: { days: 3 } },
  '72h1':{ next: '72h2', delay: { days: 1 } },
  '72h2':{ next: '72h3', delay: { days: 1 } },
  '72h3':{ next: '7d1',  delay: { days: 4 } },
  '7d1': { next: '7d2',  delay: { days: 1 } },
  '7d2': { next: '7d3',  delay: { days: 1 } },
  '7d3': { next: '10d',  delay: { days: 3 } },
  '10d': { next: 'm1',   delay: { months: 1 } },
  'm1':  { next: 'm2',   delay: { months: 1 } },
  'm2':  { next: 'm3',   delay: { months: 1 } },
  'm3':  { next: 'm4',   delay: { months: 1 } },
  'm4':  { next: 'm5',   delay: { months: 1 } },
  'm5':  { next: 'm6',   delay: { months: 1 } },
  'm6':  { next: null,   delay: null },
};

const T = {
  '6h':  'Hola {name}, ¿cómo estás? Pudiste ver mi mensaje anterior?',
  '6h2': 'Con la información que me diste, ya podés dar el siguiente paso: organizarnos para que puedas ver tu casa terminada antes de construirla y saber cuánto saldría hacerla 🏡',
  '6h3': '¿Querés que coordinemos? Es una reunión corta, sin compromiso, pero muy útil para ordenar ideas y tomar buenas decisiones desde el inicio',
  '24h1':'Hola {name}, te escribo nuevamente porque realmente creo que esta reunión puede ayudarte mucho',
  '24h2':'No es solo para hablar de metros cuadrados. Te cuento cómo organizarte económica y emocionalmente para que este proceso no se vuelva una carga',
  '24h3':'Si te interesa, decime un horario que te quede cómodo y te agendo yo 📅',
  '72h1':'Hola {name}, ¿cómo estás? No quiero insistir, pero muchas personas me dicen que esta charla les cambió totalmente la forma de encarar su casa',
  '72h2':'En solo 30 minutos, te explico cómo ordenar prioridades, evitar errores comunes y encarar tu proyecto con más seguridad',
  '72h3':'¿Te gustaría que coordinemos esta semana?',
  '7d1': 'Hola {name}, ya pasó una semana desde que completaste el formulario. ¿Pudiste avanzar con algo de lo que tenías pensado?',
  '7d2': 'Si todavía estás en esa etapa de dudas o de no saber por dónde arrancar, la llamada puede darte muchísima claridad',
  '7d3': 'Estoy disponible esta semana, ¿querés que veamos un horario?',
  '10d': 'Hola {name}.\n\nSé que esta llamada te puede ayudar mucho a encarar tu proyecto, pero no quiero insistirte. Si ahora no es el momento, está todo bien. Cuando quieras retomar, escribinos a este número y lo vemos juntos.',
  'm1':  'Hola {name}, ¿cómo estás?\n\nAlgo que pocas personas saben al construir su casa es que el diseño puede hacerte ahorrar o gastar de más.\n\nPor ejemplo, la cantidad de metros cuadrados no es lo único que define el costo: pequeñas decisiones como el tipo de materiales, la distribución de los ambientes o la orientación de la casa pueden impactar fuerte en el presupuesto final.\n\nNosotros nos especializamos en optimizar el diseño para que no gastes de más sin necesidad.\n\nSi te interesa ver cómo podríamos hacerlo con tu proyecto, avisame y lo charlamos!',
  'm2':  'Hola {name},\n\nMucha gente cuando empieza a construir comete el mismo error: arrancar sin tener un presupuesto detallado y bien armado.\n\nEl problema es que a mitad de obra aparecen costos imprevistos que pueden aumentar el gasto total hasta un 30%.\n\nPor eso, la mejor forma de evitar sorpresas es tener un diseño optimizado y un plan claro desde el primer día.\n\nSi todavía estás con la idea de construir, podemos ayudarte a hacerlo de la forma más eficiente posible. ¿Querés que lo charlemos?',
  'm3':  'Hola {name},\n\nSeguro ya viste precios por metro cuadrado, pero la pregunta clave es: ¿cuánto te va a costar realmente tu casa?\n\nEl precio promedio del mercado es solo una referencia: el costo final depende de la distribución y el diseño de los espacios, la cantidad y calidad de los materiales, y la eficiencia en la construcción.\n\nNosotros nos enfocamos en optimizar todos estos factores para reducir costos sin afectar la calidad.\n\nSi querés asegurarte de que tu presupuesto esté bien ajustado antes de empezar, escribime y lo vemos!',
  'm4':  'Hola {name},\n\nAlgo que mucha gente no tiene en cuenta cuando arranca su obra es que los sobrecostos pueden aparecer en cualquier etapa.\n\nLas 3 razones más comunes son:\n❌ Cambios de último momento en el diseño.\n❌ No tener un presupuesto detallado antes de empezar.\n❌ Mal cálculo en materiales y mano de obra.\n\nPor eso, una buena planificación desde el principio te puede ahorrar tiempo, estrés y mucha plata.\n\nSi querés asegurarte de evitar estos problemas, avisame y lo charlamos!',
  'm5':  'Hola {name},\n\nUno de los mayores dolores de cabeza al construir es que las obras suelen demorarse más de lo esperado.\n\n¿Por qué pasa esto?\n🕑 Malas estimaciones en tiempos de obra.\n🚧 Problemas con permisos y aprobaciones.\n📉 Falta de planificación en el diseño y materiales.\n\nLo que hacemos en Estudio VArq es ayudarte a tener todo resuelto antes de empezar, para que la construcción no se vuelva un dolor de cabeza.\n\nSi querés asegurarte de que tu proyecto arranque y termine en tiempo, escribime y lo hablamos!',
  'm6':  'Hola {name},\n\nHace un tiempo hablamos sobre tu proyecto. Si todavía estás con la idea de construir, nos encantaría ayudarte a planificarlo para que no gastes de más.\n\nSi te interesa que lo veamos juntos, escribime y lo coordinamos.\n\nSi no, no hay problema: cualquier cosa, sabés que podés contar con nosotros cuando lo necesites.\n\n¡Saludos! 😊',
};

const out = [];
for (const it of $input.all()) { const RL = (it && it.json) ? it.json : it; const lead = RL;
  const etapa = String(lead.etapa_seg || '');
  const stage = CHAIN[etapa];
  if (!stage) continue;
  const status = String(lead.status || '');
  if (status !== 'cualificado' && status !== 'no_cualificado') continue;
  if (!lead.prox_seg_ts || new Date(lead.prox_seg_ts).getTime() > Date.now()) continue;
  if (!laboral) continue;
  const name = String(lead.name || '').trim();
  const message = (T[etapa] || '').replace(/\{name\}/g, name || 'cliente');
  if (!message) continue;
  const sheet_update = {
    etapa_seg: stage.next || '',
    prox_seg_ts: stage.next ? $now.plus(stage.delay).toISO() : '',
    ultimo_msg_ts: now.toISO(),
  };
  if (!stage.next) sheet_update.status = 'inactivo';
  out.push({ json: { phone: String(lead.phone || ''), name, message, etapa_actual: etapa, sheet_update } });
}
return out;

